import{_ as t,o,c as r,ag as a}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Privacy settings","description":"","frontmatter":{"source":"setup/privacy-settings.md"},"headers":[],"relativePath":"setup/privacy-settings.md","filePath":"setup/privacy-settings.md"}'),s={name:"setup/privacy-settings.md"};function n(i,e,l,h,d,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="privacy-settings" tabindex="-1">Privacy settings <a class="header-anchor" href="#privacy-settings" aria-label="Permalink to &quot;Privacy settings&quot;">​</a></h1><blockquote><p>Change these <strong>before</strong> you type anything into an AI tool. Click-paths checked 21 Oct 2026.</p></blockquote><p>Most free AI tools keep what you type. Many use it to <strong>train</strong> future models (the model learns from your conversation), and some let <strong>human reviewers</strong> read samples. That&#39;s the price of a free tier. You can&#39;t always avoid it, but you can limit it.</p><p>Three rules cover every tool, including ones that aren&#39;t on this page:</p><ol><li><strong>Opt out of training</strong> wherever there&#39;s a setting for it.</li><li><strong>Use a temporary chat</strong> for anything you&#39;d rather not have stored.</li><li><strong>Never paste secrets or other people&#39;s data</strong>, into any tool, whatever its settings say. That means no API keys, passwords, tokens, <code>.env</code> files, or personal information about other people (safety contract <a href="./safety-contract.html#2-i-never-paste-secrets-or-other-peoples-data-into-an-ai-tool">rule 2</a>).</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Menus move.</strong> AI companies redesign their settings pages often. If you can&#39;t find a setting named here, ask the assistant itself (&quot;Where is the setting that stops my chats being used for training?&quot;) or search the company&#39;s help pages. If a click-path here is wrong, please tell your instructor so it can be fixed.</p></div><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Used for training by default?</th><th>What to change</th><th>Temporary chats</th></tr></thead><tbody><tr><td><a href="#chatgpt">ChatGPT</a></td><td>Yes</td><td>Turn off &quot;Improve the model for everyone&quot;</td><td>Yes</td></tr><tr><td><a href="#claude">Claude</a></td><td>Yes, unless you opt out</td><td>Turn off &quot;Help improve Claude&quot;</td><td>Yes (incognito)</td></tr><tr><td><a href="#gemini">Gemini</a></td><td>Yes, while Keep Activity is on, with human review of samples</td><td>Turn off Keep Activity</td><td>Yes</td></tr><tr><td><a href="#github-copilot">GitHub Copilot</a></td><td>Yes, on the Free plan</td><td>Turn off use of your data for training</td><td>No</td></tr><tr><td><a href="#google-ai-studio-and-the-gemini-api">Google AI Studio and the Gemini API</a></td><td>Yes, with human review (except in the EEA, UK and Switzerland)</td><td><strong>No opt-out on the free tier</strong></td><td>No</td></tr><tr><td><a href="#browser-app-builders-bolt-lovable-v0-replit">Browser app builders</a></td><td>Assume yes</td><td>No opt-out we could confirm</td><td>No</td></tr><tr><td><a href="#google-antigravity">Google Antigravity</a></td><td>Not stated</td><td>Turn off data collection in Settings</td><td>No</td></tr><tr><td><a href="#groq-and-openrouter">Groq and OpenRouter</a></td><td>Groq: no. OpenRouter: depends on the model&#39;s provider</td><td>Review OpenRouter&#39;s privacy settings</td><td>Not applicable</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Shared chat links are public.</strong> In this course you record the prompts that mattered in <code>PROMPTS.md</code>, either by copying the prompt in or, where a tool lets you, by pasting a share link to the chat. Anyone with that link can read the whole conversation. Before you share, scroll through and check it contains nothing personal and no keys.</p></div><h2 id="chatgpt" tabindex="-1">ChatGPT <a class="header-anchor" href="#chatgpt" aria-label="Permalink to &quot;ChatGPT&quot;">​</a></h2><p><strong>What&#39;s collected by default.</strong> Your conversations can be used to train OpenAI&#39;s models (<a href="https://help.openai.com/en/articles/5722486-how-your-data-is-used-to-improve-model-performance" target="_blank" rel="noreferrer">OpenAI Help: how your data is used</a>).</p><p><strong>Change this setting.</strong> Click your profile icon → <strong>Settings</strong> → <strong>Data controls</strong> → turn <strong>Improve the model for everyone</strong> off.</p><p><strong>Temporary chats.</strong> Start a new chat and click <strong>Temporary</strong> (at the top of the chat). A temporary chat isn&#39;t saved in your history and isn&#39;t used for training (<a href="https://help.openai.com/en/articles/7730893-data-controls-in-chatgpt" target="_blank" rel="noreferrer">OpenAI Help: data controls</a>).</p><p><strong>Also check.</strong> ChatGPT can remember facts about you across chats (<strong>Settings</strong> → <strong>Personalization</strong> → <strong>Memory</strong>). Review what it has saved, or turn memory off if you&#39;d rather it didn&#39;t. If you&#39;re under 18, ChatGPT needs a parent&#39;s consent and gives you a separate teen experience.</p><h2 id="claude" tabindex="-1">Claude <a class="header-anchor" href="#claude" aria-label="Permalink to &quot;Claude&quot;">​</a></h2><p><strong>What&#39;s collected by default.</strong> On the Free, Pro and Max plans, chats and coding sessions are used to train Anthropic&#39;s models unless you opt out. If you allow training, Anthropic keeps your data for much longer (<a href="https://www.anthropic.com/news/updates-to-our-consumer-terms" target="_blank" rel="noreferrer">Anthropic: updates to consumer terms</a>). Claude is for adults only (18+).</p><p><strong>Change this setting.</strong> Click your name or initials (bottom left) → <strong>Settings</strong> → <strong>Privacy</strong> → turn <strong>Help improve Claude</strong> off.</p><p><strong>Temporary chats.</strong> Start a new chat and turn on <strong>incognito</strong> (the ghost icon near the top of the chat). Incognito chats aren&#39;t saved to your history and aren&#39;t used for training.</p><p><strong>Also check.</strong> Third-party reports say that chats flagged by Anthropic&#39;s safety systems may still be used even when the setting is off. Another reason to keep personal data out of every chat.</p><h2 id="gemini" tabindex="-1">Gemini <a class="header-anchor" href="#gemini" aria-label="Permalink to &quot;Gemini&quot;">​</a></h2><p><strong>What&#39;s collected by default.</strong> While <strong>Keep Activity</strong> is on, Google saves your chats. A sample of chats <strong>and uploaded files</strong> may be read by human reviewers and used to improve Google&#39;s products. Chats that a person has already reviewed are kept separately, even if you later delete your activity (<a href="https://support.google.com/gemini/answer/13594961?hl=en" target="_blank" rel="noreferrer">Gemini Apps Privacy Hub</a>).</p><p><strong>Change this setting.</strong> On <a href="https://gemini.google.com/" target="_blank" rel="noreferrer">gemini.google.com</a>, open <strong>Settings &amp; help</strong> (bottom left) → <strong>Activity</strong> → <strong>Keep activity</strong> → <strong>Turn off</strong>. You can also choose to delete your past activity at the same time.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>The course setting: keep it off.</strong> With Keep Activity off, Gemini doesn&#39;t keep your chat history, so you can&#39;t reopen yesterday&#39;s chat or share a link to it. That&#39;s the trade-off, and the course accepts it. Copy each prompt that mattered (and the final code, before you close the tab) into your <code>PROMPTS.md</code> as you go. Where a lab says &quot;save your chat&quot;, this is what it means for Gemini.</p></div><p><strong>Temporary chats.</strong> Click the <strong>Temporary chat</strong> icon next to <strong>New chat</strong>. Temporary chats don&#39;t appear in your history and aren&#39;t used to train Google&#39;s models. Google still keeps them for a short time to run the service.</p><p><strong>Also check.</strong> Use your <strong>personal</strong> Google account. School and work accounts follow the organization&#39;s rules, and an administrator may have switched Gemini off.</p><h2 id="github-copilot" tabindex="-1">GitHub Copilot <a class="header-anchor" href="#github-copilot" aria-label="Permalink to &quot;GitHub Copilot&quot;">​</a></h2><p><strong>What&#39;s collected by default.</strong> GitHub uses &quot;interaction data&quot; from Copilot Free, Pro and Pro+ to train AI models by default. That means your prompts, Copilot&#39;s suggestions, and the code around your cursor (<a href="https://github.blog/news-insights/company-news/updates-to-github-copilot-interaction-data-usage-policy/" target="_blank" rel="noreferrer">GitHub blog: Copilot interaction data policy</a>). GitHub&#39;s FAQ suggests that students who get Copilot through GitHub Education are excluded, but the policy doesn&#39;t say so clearly, so turn the setting off anyway if you see it.</p><p><strong>Change this setting.</strong> On github.com: profile photo → <strong>Settings</strong> → <strong>Copilot</strong> (left sidebar) → <strong>Features</strong> (or go straight to <a href="https://github.com/settings/copilot/features" target="_blank" rel="noreferrer">github.com/settings/copilot/features</a>) → find the setting that allows GitHub to use your data for AI model training → <strong>Disabled</strong>. This one setting covers Copilot everywhere you use it: Codespaces, VS Code on your laptop, and Copilot CLI in the terminal.</p><p>While you&#39;re on that page, you can also set <strong>Suggestions matching public code</strong> to <strong>Block</strong>. Copilot will then avoid suggesting code that copies public code word for word.</p><p><strong>Temporary chats.</strong> None. The training setting applies to all your Copilot use.</p><p><strong>Also check.</strong></p><ul><li>Copilot reads the files in the folder you have open. Keep <code>.env</code> files and real documents out of your project folders (safety contract rule 4).</li><li>VS Code sends usage statistics (telemetry) by default. To turn that off: in VS Code, open <strong>Settings</strong>, search for <code>telemetry</code>, and set <strong>Telemetry Level</strong> to <strong>off</strong>.</li></ul><h2 id="google-ai-studio-and-the-gemini-api" tabindex="-1">Google AI Studio and the Gemini API <a class="header-anchor" href="#google-ai-studio-and-the-gemini-api" aria-label="Permalink to &quot;Google AI Studio and the Gemini API&quot;">​</a></h2><p><strong>What&#39;s collected by default.</strong> On the free (unpaid) tier, Google uses what you submit to improve its products, and <strong>human reviewers may read, annotate and process your input and output</strong> (<a href="https://ai.google.dev/gemini-api/terms" target="_blank" rel="noreferrer">Gemini API Additional Terms</a>). This covers everything you type into AI Studio, including <em>Build</em> mode in week 6. It also covers every request your app sends with a free Gemini API key in weeks 9–16, so it includes <strong>whatever your app&#39;s users type</strong>.</p><p>In the <strong>EEA, the UK and Switzerland</strong>, Google applies its paid-service data terms even to free use. That exemption is set out in the same terms.</p><p><strong>Change this setting.</strong> There is <strong>no opt-out on the free tier</strong>. <strong>Never paste personal or secret data</strong> into AI Studio, and never send real people&#39;s personal data through an app that uses a free key. Use made-up test data.</p><p><strong>Temporary chats.</strong> They don&#39;t change these terms. Treat everything you type as something a person might read.</p><p><strong>Also check.</strong></p><ul><li>AI Studio is for adults only (18+).</li><li>Your <strong>API key is a password.</strong> Keep it in a <code>.env</code> file or a Codespaces secret (<a href="./codespaces.html#keep-secrets-in-codespaces-secrets">how</a>). Never commit it, paste it into a chat, or put it in front-end code. Delete keys you no longer use from AI Studio&#39;s API keys page. (Not every key is a secret: in week 13 you&#39;ll meet one that is public by design, the Supabase <em>publishable</em> key. AI API keys are always secret.)</li></ul><h2 id="browser-app-builders-bolt-lovable-v0-replit" tabindex="-1">Browser app builders (Bolt, Lovable, v0, Replit) <a class="header-anchor" href="#browser-app-builders-bolt-lovable-v0-replit" aria-label="Permalink to &quot;Browser app builders (Bolt, Lovable, v0, Replit)&quot;">​</a></h2><p><strong>What&#39;s collected by default.</strong> The research behind this course couldn&#39;t confirm each builder&#39;s training settings for free accounts. v0 lists &quot;training opt-out by default&quot; as a feature of its paid Business plan, which suggests that free-plan data may be used for training (<a href="https://v0.app/pricing" target="_blank" rel="noreferrer">v0 pricing</a>). Assume the same of every builder unless its settings say otherwise. Some builders also make free projects <strong>public</strong>, or show them in a community gallery. And platforms have flaws of their own: in 2026 a missing check in one builder&#39;s project API let any free account read other users&#39; source code, database keys and AI chat history (<a href="https://dev.to/alejandxr/lovable-bola-48-days-five-api-calls-source-code-database-credentials-of-other-peoples-projects-4ai0" target="_blank" rel="noreferrer">Sable Offensive Research</a>).</p><p><strong>Change this setting.</strong> No opt-out on the free tiers that we could confirm, so <strong>never paste personal or secret data</strong>. Two things you can do:</p><ul><li><strong>Check each project&#39;s visibility</strong> (public or private) in the builder&#39;s project settings. Make practice projects private if the free plan allows it.</li><li>If the builder offers to connect a database, a payment service or another account, <strong>don&#39;t connect real accounts</strong>. The week 6 bake-off doesn&#39;t need any.</li></ul><p><strong>Temporary chats.</strong> None.</p><p><strong>Also check.</strong> When a builder asks for access to your GitHub account, choose <strong>Only select repositories</strong>. Export your project to GitHub at the end of every session: builders change their free plans often, and some delete free projects after a while.</p><h2 id="google-antigravity" tabindex="-1">Google Antigravity <a class="header-anchor" href="#google-antigravity" aria-label="Permalink to &quot;Google Antigravity&quot;">​</a></h2><p><strong>What&#39;s collected by default.</strong> Google says you can opt out of data collection from Antigravity&#39;s Settings panel. Whether the free plan uses your data to train models isn&#39;t stated (<a href="https://antigravity.google/docs/faq" target="_blank" rel="noreferrer">Antigravity FAQ</a>). Antigravity is for adults only (18+) and needs a personal Google account.</p><p><strong>Change this setting.</strong> Open Antigravity&#39;s <strong>Settings</strong> panel and turn off the data-collection option.</p><p><strong>Temporary chats.</strong> None.</p><p><strong>Also check.</strong> Antigravity is an <strong>agent</strong>: it can read and change files and run commands on your own computer. In one reported case, an agent asked to clear a cache wiped a user&#39;s entire drive (<a href="https://www.tomshardware.com/tech-industry/artificial-intelligence/googles-agentic-ai-wipes-users-entire-hard-drive-without-permission-after-misinterpreting-instructions-to-clear-a-cache-i-am-deeply-deeply-sorry-this-is-a-critical-failure-on-my-part" target="_blank" rel="noreferrer">Tom&#39;s Hardware</a>).</p><ul><li><strong>Approvals on, always.</strong> In Settings, find the options that control whether the agent runs terminal commands automatically, and choose the ones that <strong>ask you first</strong>. Never turn on a mode that lets it act without asking (safety contract <a href="./safety-contract.html#9-agents-dont-publish-and-untrusted-content-never-shares-a-session-with-my-secrets">rule 9</a>).</li><li>Open only a single project folder, never your home folder or a whole drive.</li><li>Commit before and after every agent task (safety contract rule 3).</li></ul><h2 id="groq-and-openrouter" tabindex="-1">Groq and OpenRouter <a class="header-anchor" href="#groq-and-openrouter" aria-label="Permalink to &quot;Groq and OpenRouter&quot;">​</a></h2><p>These are <strong>LLM APIs</strong>: services your app calls from its server code in weeks 9–16. There&#39;s no chat window and no history for you to manage. What matters is what your app sends them.</p><p><strong>What&#39;s collected by default.</strong></p><ul><li><strong>Groq</strong> doesn&#39;t keep the content of your requests by default (<a href="https://console.groq.com/docs/your-data" target="_blank" rel="noreferrer">Groq: your data</a>).</li><li><strong>OpenRouter</strong> doesn&#39;t log your prompts by default. But OpenRouter passes each request on to another company that runs the model, and some of those companies, especially for <strong>free</strong> models, may log your prompts or train on them (<a href="https://openrouter.ai/docs/guides/privacy/provider-logging" target="_blank" rel="noreferrer">OpenRouter: provider logging</a>).</li></ul><p><strong>Change this setting.</strong></p><ul><li><strong>Groq:</strong> nothing to change.</li><li><strong>OpenRouter:</strong> open your account&#39;s <strong>Settings</strong> → <strong>Privacy</strong> and read the options. They control whether your requests may go to providers that log or train on prompts. Some free models only work if you allow that, which is exactly why you never send personal data through them.</li></ul><p><strong>Temporary chats.</strong> Not applicable.</p><p><strong>Also check.</strong> Everything your app&#39;s users type is sent to the provider, so the app must never ask for real personal data. Keep keys in <code>.env</code> or a Codespaces secret, never in front-end code.</p><h2 id="cloudflare-workers-ai-and-ollama" tabindex="-1">Cloudflare Workers AI and Ollama <a class="header-anchor" href="#cloudflare-workers-ai-and-ollama" aria-label="Permalink to &quot;Cloudflare Workers AI and Ollama&quot;">​</a></h2><ul><li><strong>Cloudflare Workers AI</strong> (a fallback LLM API): the course&#39;s research didn&#39;t confirm how Cloudflare uses request data. Follow the three rules at the top of this page.</li><li><strong>Ollama</strong> (a fallback that runs models on your own computer): when the model runs locally, your prompts never leave your machine. That makes it the most private option, if your computer is powerful enough (see <a href="./../TOOLS.html">Tool Handout</a>). Ollama&#39;s cloud service is different: read its terms before you use it.</li></ul><h2 id="your-github-account-and-commits" tabindex="-1">Your GitHub account and commits <a class="header-anchor" href="#your-github-account-and-commits" aria-label="Permalink to &quot;Your GitHub account and commits&quot;">​</a></h2><p>GitHub isn&#39;t an AI tool, but it&#39;s public by default, and everything you commit to a public repository stays visible in its history.</p><ul><li><strong>Your email address.</strong> Every commit records an email address. Go to <strong>Settings</strong> → <strong>Emails</strong> and tick <strong>Keep my email addresses private</strong> and <strong>Block command line pushes that expose my email</strong>.</li><li><strong>Your profile.</strong> Your username, profile photo and anything in your bio are public. Share only what you&#39;re happy for employers and strangers to see.</li><li><strong>Deleting isn&#39;t erasing.</strong> If you commit a secret and delete it in the next commit, it&#39;s still in the history. Revoke the secret and make a new one. See <a href="./github-basics.html#public-or-private">GitHub basics: Public or private</a>.</li></ul><h2 id="any-other-ai-tool" tabindex="-1">Any other AI tool <a class="header-anchor" href="#any-other-ai-tool" aria-label="Permalink to &quot;Any other AI tool&quot;">​</a></h2><p>Before you use a tool that isn&#39;t on this page, spend two minutes answering:</p><ul><li>☐ Does it train on what I type by default? Where is the opt-out?</li><li>☐ Can people (reviewers, or the public) see my chats or projects?</li><li>☐ Does it have a temporary or incognito mode?</li><li>☐ What is its minimum age, and is it available where I live?</li><li>☐ Does it store my API keys on its own servers? If it offers a hosted &quot;console&quot; for your keys, prefer keeping them in your own environment variables: in October 2026 an intruder reached one coding tool&#39;s hosted console and ran up charges on users&#39; stored AI keys (<a href="https://techcrunch.com/2026/10/19/hackers-hit-ai-coding-tool-opencode-running-up-charges-on-users-ai-accounts/" target="_blank" rel="noreferrer">TechCrunch</a>).</li><li>☐ Where is the data stored? (For example, the course doesn&#39;t require DeepSeek, which stores data in China and is banned on government devices in several countries: <a href="https://techcrunch.com/2025/02/03/deepseek-the-countries-and-agencies-that-have-banned-the-ai-companys-tech" target="_blank" rel="noreferrer">TechCrunch</a>.)</li></ul><p>If you can&#39;t find the answers, treat the tool as public: nothing personal, nothing secret.</p><p>Back to <a href="./">Week 0 pre-work</a> · Current tools and limits: <a href="./../TOOLS.html">Tool Handout</a></p>',69)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
